WITH with_windows AS (SELECT *, LAG(monthly_fee, 1) OVER (PARTITION BY status ORDER BY end_date, id) AS prev_monthly_fee, LAG(monthly_fee, 1, 0) OVER (PARTITION BY status ORDER BY start_date, id) AS prev_monthly_fee_2 FROM subscriptions) SELECT id, customer_id, start_date, end_date, status, prev_monthly_fee_2, CASE WHEN status RLIKE '^(CANCELLED|PAUSED)$' THEN 'CORE' ELSE 'EXTENDED' END AS status_zone FROM with_windows;
